# 데이터 버전 관리(DVC) 예시: Python 3에서 실행 가능한 코드
experiment = {"code": "a1b2", "data": "v3"}
print(experiment["code"], experiment["data"])

# 실험 추적(MLflow) 예시: Python 3에서 실행 가능한 코드
run = {"lr": 0.01, "accuracy": 0.91}
print(f"acc={run["accuracy"]}")

# 모델 레지스트리 예시: Python 3에서 실행 가능한 코드
registry = {"fraud-model": {"version": 4, "stage": "prod"}}
print(registry["fraud-model"]["stage"])

# 피처 스토어(심화) 예시: Python 3에서 실행 가능한 코드
features = {"user_age": 31, "avg_order": 42000}
print(features["avg_order"])

# 온라인 피처 서빙 예시: Python 3에서 실행 가능한 코드
online_store = {"u1": {"visits": 5}}
print(online_store["u1"]["visits"])

# 데이터 드리프트 예시: Python 3에서 실행 가능한 코드
train = {"mobile": 0.6}
prod = {"mobile": 0.85}
print(prod["mobile"] - train["mobile"])

# 모델 모니터링 예시: Python 3에서 실행 가능한 코드
metrics = {"latency_ms": 80, "error_rate": 0.01}
print(metrics["latency_ms"] < 100)

# 예측 로깅 예시: Python 3에서 실행 가능한 코드
log = {"model": "v2", "score": 0.87, "request": "r1"}
print(log["model"], log["score"])

# 챔피언-챌린저 배포 예시: Python 3에서 실행 가능한 코드
scores = {"champion": 0.91, "challenger": 0.93}
print(max(scores, key=scores.get))

# 멀티암드 밴딧(모델 선택) 예시: Python 3에서 실행 가능한 코드
rewards = {"A": 10, "B": 18, "C": 12}
print(max(rewards, key=rewards.get))

# REST 서빙 예시: Python 3에서 실행 가능한 코드
request = {"features": [1, 2, 3]}
response = {"score": sum(request["features"])}
print(response)

# gRPC 서빙 예시: Python 3에서 실행 가능한 코드
payload = {"vector": [0.1, 0.2]}
print(len(payload["vector"]))

# Triton Inference Server 예시: Python 3에서 실행 가능한 코드
server = {"models": ["resnet", "bert"], "dynamic_batching": True}
print(server["dynamic_batching"])

# KServe 예시: Python 3에서 실행 가능한 코드
inference_service = {"name": "fraud", "replicas": 2}
print(inference_service["name"])

# vLLM 예시: Python 3에서 실행 가능한 코드
engine = {"paged_attention": True, "batching": "continuous"}
print(engine["paged_attention"])

# 페이지드 어텐션(PagedAttention) 예시: Python 3에서 실행 가능한 코드
pages = {"req1": [1, 4], "req2": [2]}
print(sum(len(v) for v in pages.values()))

# AI 거버넌스 예시: Python 3에서 실행 가능한 코드
policy = {"approved": True, "owner": "risk-team"}
print(policy["approved"])

# 모델 카드 예시: Python 3에서 실행 가능한 코드
card = {"task": "classification", "limitations": ["small dataset"]}
print(card["task"])

# 책임 있는 AI 예시: Python 3에서 실행 가능한 코드
checks = {"fairness": True, "privacy": True, "accuracy": True}
print(all(checks.values()))

# 편향 탐지 예시: Python 3에서 실행 가능한 코드
rates = {"group_a": 0.8, "group_b": 0.62}
print(abs(rates["group_a"] - rates["group_b"]) > 0.1)

# 데이터셋 버전 관리 예시: Python 3에서 실행 가능한 코드
dataset = {"name": "orders", "version": "2026-05-01"}
print(dataset["version"])

# 학습 재현성 예시: Python 3에서 실행 가능한 코드
config = {"seed": 7, "data": "v1", "lr": 0.01}
print(tuple(sorted(config.items())))

# 데이터셋 카드(Dataset Card) 예시: Python 3에서 실행 가능한 코드
card = {"source": "survey", "rows": 5000, "license": "internal"}
print(card["rows"])

# 공정성 메트릭 예시: Python 3에서 실행 가능한 코드
fpr = {"A": 0.04, "B": 0.09}
print(max(fpr.values()) - min(fpr.values()))

# ML 모니터링 대시보드 예시: Python 3에서 실행 가능한 코드
dashboard = {"latency": 80, "drift": 0.03, "accuracy": 0.9}
print(dashboard.keys())

# 피처 중요도 모니터링 예시: Python 3에서 실행 가능한 코드
importance = {"age": 0.2, "income": 0.5, "region": 0.1}
print(max(importance, key=importance.get))
